  "sql": "WITH _base AS (\n  SELECT\n    products.category AS \"products.category\"\n  FROM products AS products\n  GROUP BY\n    products.category\n), _cm_products__ratings__value_avg AS (\n  SELECT\n    ratings.category AS \"__slayer_list__8_products__ratings.ratings.category\",\n    CAST(AVG(__slayer_list__8_products__ratings.value) AS DOUBLE) AS \"__slayer_list__8_products__ratings.value_avg\"\n  FROM products AS ratings\n  CROSS JOIN LATERAL (\n    SELECT\n      __slayer_u.value\n    FROM UNNEST(ratings.ratings) AS __slayer_u(value)\n    WHERE\n      __slayer_u.value IS NOT NULL\n  ) AS __slayer_list__8_products__ratings\n  GROUP BY\n    ratings.category\n), _cm_products__ratings__value_count AS (\n  SELECT\n    ratings.category AS \"__slayer_list__8_products__ratings.ratings.category\",\n    COUNT(__slayer_list__8_products__ratings.value) AS \"__slayer_list__8_products__ratings.value_count\"\n  FROM products AS ratings\n  CROSS JOIN LATERAL (\n    SELECT\n      __slayer_u.value\n    FROM UNNEST(ratings.ratings) AS __slayer_u(value)\n    WHERE\n      __slayer_u.value IS NOT NULL\n  ) AS __slayer_list__8_products__ratings\n  GROUP BY\n    ratings.category\n)\nSELECT\n  _base.\"products.category\",\n  _cm_products__ratings__value_avg.\"__slayer_list__8_products__ratings.value_avg\" AS \"products.avg_rating\",\n  COALESCE(\n    _cm_products__ratings__value_count.\"__slayer_list__8_products__ratings.value_count\",\n    0\n  ) AS \"products.rating_count\"\nFROM _base\nLEFT JOIN _cm_products__ratings__value_avg\n  ON _base.\"products.category\" IS NOT DISTINCT FROM _cm_products__ratings__value_avg.\"__slayer_list__8_products__ratings.ratings.category\"\nLEFT JOIN _cm_products__ratings__value_count\n  ON _base.\"products.category\" IS NOT DISTINCT FROM _cm_products__ratings__value_count.\"__slayer_list__8_products__ratings.ratings.category\"\nORDER BY\n  _base.\"products.category\" ASC\nLIMIT 101"
